  async function ask(e:React.FormEvent){e.preventDefault();try{await mutate("clarifications",{instructionId:selected,question});setQuestion("");}catch{}}
  return <>{!clinician && <section className="panel question-form"><div className="panel-heading"><h2>Ask your care team</h2><MessageCircle size={22}/></div><p>If something is missing or unclear, your care team can help.</p><form onSubmit={ask}><label>Related approved instruction<select value={selected} onChange={e=>setSelected(e.target.value)}>{instructions.map(i=><option value={i.id} key={i.id}>{i.title}</option>)}</select></label><label>Your question<textarea required minLength={5} maxLength={2000} rows={3} placeholder="What would you like to understand?" value={question} onChange={e=>setQuestion(e.target.value)}/></label><button className="button primary" disabled={pending || !selected}>Send clarification request</button></form></section>}<section className="panel"><div className="panel-heading"><h2>{clinician?"Clarification queue":"Your clarification requests"}</h2><span className="muted">{data.requests.filter(r=>r.status==="OPEN").length} awaiting reply</span></div>{data.requests.map(r=><article className="question-card" key={r.id}><div className="panel-heading"><span className="micro-label">{r.instruction.title}</span><Status status={r.status}/></div><h3>{r.question}</h3><small>{r.requestedBy.name} · {formatDate(r.createdAt,timezone)}</small>{r.response && <div className="care-team-response"><span className="micro-label"><Stethoscope size={15}/> YOUR CARE TEAM’S RESPONSE</span><p>{r.response}</p><small>Changes to instructions require a newly approved care-plan version.</small></div>}{clinician && r.status==="OPEN" && <form onSubmit={e=>{e.preventDefault();void mutate(`clarifications/${r.id}`,{response:responses[r.id]},"PATCH").catch(()=>{});}}><label>Clinician response<textarea value={responses[r.id] || ""} onChange={e=>setResponses({...responses,[r.id]:e.target.value})} required minLength={5} maxLength={3000} rows={3}/></label><p className="muted">For any instruction change, publish a new approved version through care-plan review.</p><button className="button primary" disabled={pending}>Respond and resolve</button></form>}</article>)}{!data.requests.length && <div className="empty-inline">No clarification requests yet.</div>}</section></>;
